SELECT DISTINCT sp.id, sp.name, sp.identity_card AS identityCard FROM swm_person sp LEFT JOIN fms_worker fw ON sp.identity_card COLLATE utf8mb4_general_ci = fw.identity_code COLLATE utf8mb4_general_ci
sp.identity_card IS NOT NULL AND sp.identity_card != '' AND (sp.status IS NULL OR sp.status = '' OR sp.status = '0') AND (sp.personnel_status IS NULL OR sp.personnel_status = '' OR sp.personnel_status = '1')
AND sp.company = #{id}
AND sp.department = #{id}
AND sp.prod_line = #{id}
AND (sp.team = #{id} OR fw.work_group_id = #{id})
AND 1 = 0
ORDER BY sp.name

SELECT value, MAX(label) AS label FROM ( SELECT CAST(o.office_code AS CHAR) COLLATE utf8mb4_general_ci AS value, COALESCE(NULLIF(o.office_name, ''), o.office_code) AS label FROM js_sys_office o WHERE o.office_code IN
#{id}
UNION ALL SELECT CAST(p.id AS CHAR) COLLATE utf8mb4_general_ci AS value, p.position_name AS label FROM fms_position_archive p WHERE p.id IN
#{id}
UNION ALL SELECT CAST(pl.id AS CHAR) COLLATE utf8mb4_general_ci AS value, pl.prod_line_name AS label FROM fms_prod_line pl WHERE pl.id IN
#{id}
UNION ALL SELECT CAST(wg.id AS CHAR) COLLATE utf8mb4_general_ci AS value, wg.work_group_name AS label FROM fms_work_group wg WHERE wg.id IN
#{id}
) t GROUP BY value
